enum CriaturaAnim { ANIM_FIXO, ANIM_CABECA, ANIM_PERNA_A, ANIM_PERNA_B, ANIM_CAUDA, ANIM_ASA_E, ANIM_ASA_D };
enum CriaturaTipo { TIPO_FOGO, TIPO_AGUA, TIPO_PLANTA, TIPO_ELETRICO, TIPO_VENTO, TIPO_PEDRA, TIPO_INSETO, TIPO_FANTASMA, TIPO_GELO, TIPO_COUNT };
enum CriaturaHabitat { HABITAT_CAMPO, HABITAT_AREIA, HABITAT_AGUA, HABITAT_ALTO, HABITAT_PEDRA, HABITAT_NEVE, HABITAT_NOITE };

struct PecaDef { cc_uint8 u, v; cc_int8 x1,y1,z1, x2,y2,z2, px,py,pz; cc_uint8 anim; };
struct PlanoDef { const struct PecaDef* pecas; int count; float nameY, eyeY; cc_int8 bb[6]; };
struct EspecieDef { const char* nome; const char* cor; cc_uint8 tipo, plano; float escala;
	cc_uint8 vida, dano; float vel; int evolui, nivelEvolui; cc_uint8 habitat, inicial;
	const cc_uint8* png; int pngLen; const char* desc; };

